import math

def test_four_tokens():
    logs = [0.0, -math.log(2), -math.log(2), -math.log(4)]
    assert abs(solution.perplexity(logs) - 2.0) < 1e-9

def test_single_token():
    assert solution.perplexity([0.0]) == 1.0

def test_uniform_ten():
    logs = [-math.log(10)] * 10
    assert abs(solution.perplexity(logs) - 10.0) < 1e-9

def test_empty_raises():
    try:
        solution.perplexity([])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_positive_raises():
    try:
        solution.perplexity([0.1, -0.2])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_returns_float():
    assert isinstance(solution.perplexity([-1.0]), float)
